function leadTable(rows){if(!rows.length)return '<div class="empty">No leads yet. Add every genuine enquiry here so no opportunity gets forgotten.</div>';return `<div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Business / Person</th><th>Service</th><th>Status</th><th>Follow-up</th><th></th></tr></thead><tbody>${rows.map(l=>`<tr><td>${esc(l.date||'—')}</td><td><strong>${esc(l.business)}</strong><br><span style="color:var(--muted)">${esc(l.contact||'')}</span></td><td>${esc(l.service||'—')}</td><td><span class="badge">${esc(l.status)}</span></td><td>${esc(l.followUp||'—')}</td><td><button class="btn" data-edit-lead="${esc(l.id)}">Edit</button></td></tr>`).join('')}</tbody></table></div>`}

function invoiceStatus(s){return `<span class="invoice-status ${String(s||'Draft').toLowerCase().replace(/\s+/g,'-')}">${esc(s||'Draft')}</span>`}
function invoiceMini(){if(!invoices.length)return '<div class="empty">No invoices yet.<br><br><button class="btn primary" data-add="invoice">Create first invoice</button></div>';return invoices.slice(0,5).map(i=>`<div class="invoice-card"><div class="invoice-card-head"><div><div class="invoice-number">${esc(i.invoice_number)}</div><strong>${esc(i.client_name)}</strong></div><div style="text-align:right"><div class="invoice-total">${money(i.total)}</div>${invoiceStatus(i.status)}</div></div></div>`).join('')}
function renderInvoices(filter=''){title.textContent='Invoices';const rows=invoices.filter(i=>`${i.invoice_number} ${i.client_name} ${i.status}`.toLowerCase().includes(filter.toLowerCase()));content.innerHTML=`<div class="section-head"><div><h2>Invoices</h2><p>Create invoices from quotations, track balances and payment status.</p></div><div class="quote-toolbar"><input id="invoiceSearch" class="search" placeholder="Search invoices..." value="${esc(filter)}"><button class="btn primary" data-add="invoice">+ New Invoice</button></div></div><div class="panel">${invoiceTable(rows)}</div>`;document.getElementById('invoiceSearch').addEventListener('input',e=>renderInvoices(e.target.value))}
