function paymentInvoiceOptions(selected=''){return '<option value="">Select an invoice...</option>'+invoices.map(i=>'<option value="'+esc(i.id)+'" '+(i.id===selected?'selected':'')+'>'+esc(i.invoice_number)+' — '+esc(i.client_name)+' — Balance '+money(i.balance_due)+'</option>').join('')}
function paymentForm(p={}){p=p||{};return '<div class="form-grid"><div class="field"><label>Invoice *</label><select name="invoice_id" required>'+paymentInvoiceOptions(p.invoice_id||'')+'</select></div><div class="field"><label>Payment number</label><input name="payment_number" value="'+esc(p.payment_number||'')+'" placeholder="Auto-generated on save" readonly></div><div class="field"><label>Payment date *</label><input type="date" name="payment_date" value="'+esc(p.payment_date||today())+'" required></div><div class="field"><label>Amount (R) *</label><input name="amount" type="number" min="0.01" step="0.01" value="'+Number(p.amount||0).toFixed(2)+'" required></div><div class="field"><label>Payment method *</label><select name="method">'+['EFT','Cash','Card','PayPal','Other'].map(x=>'<option '+(x===(p.method||'EFT')?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="field"><label>Payment reference</label><input name="reference" value="'+esc(p.reference||'')+'" placeholder="Bank reference / receipt number"></div><div class="field" style="grid-column:1/-1"><label>Notes</label><textarea name="notes" placeholder="Optional payment notes">'+esc(p.notes||'')+'</textarea></div></div><div class="quote-summary" id="paymentSummary"></div><div class="form-actions"><button type="button" class="btn" id="cancelModal">Cancel</button><button class="btn primary">Save Payment</button></div>'}
function calculatePayment(){const invoiceId=form.querySelector('[name="invoice_id"]')?.value,invoice=invoices.find(i=>i.id===invoiceId),amount=Math.max(0,Number(form.querySelector('[name="amount"]')?.value||0));if(!invoice){form.querySelector('#paymentSummary').innerHTML='<div class="empty">Select an invoice to see its balance.</div>';return {invoice:null,amount:0,newPaid:0,newBalance:0}}const allRecorded=payments.filter(p=>p.invoice_id===invoice.id),recordedTotal=allRecorded.reduce((s,p)=>s+Number(p.amount||0),0),recordedBefore=allRecorded.filter(p=>p.id!==form.dataset.paymentId).reduce((s,p)=>s+Number(p.amount||0),0),openingPaid=Math.max(0,Number(invoice.amount_paid||0)-recordedTotal),previouslyPaid=openingPaid+recordedBefore,newPaid=Math.min(Number(invoice.total||0),previouslyPaid+amount),newBalance=Math.max(0,Number(invoice.total||0)-newPaid);form.querySelector('#paymentSummary').innerHTML='<div class="quote-summary-row"><span>Invoice total</span><strong>'+money(invoice.total)+'</strong></div><div class="quote-summary-row"><span>Previously paid</span><strong>'+money(openingPaid)+'</strong></div><div class="quote-summary-row"><span>This payment</span><strong>'+money(amount)+'</strong></div><div class="quote-summary-row total"><span>New balance</span><strong>'+money(newBalance)+'</strong></div>';return {invoice,amount,newPaid,newBalance}}
async function nextPaymentNumber(session){const {data,error}=await window.kasituSupabase.from('payments').select('payment_number').eq('owner_id',session.user.id);if(error)throw error;const nums=(data||[]).map(r=>Number(String(r.payment_number||'').match(/^KAS-P-\d{4}-(\d+)$/)?.[1]||0)).filter(Number.isFinite);return 'KAS-P-'+new Date().getFullYear()+'-'+String(Math.max(0,...nums)+1).padStart(3,'0')}
async function savePayment(existing){const session=await getSession();if(!session)return;const v=values(),calc=calculatePayment();if(!calc.invoice){alert('Please select an invoice.');return}if(calc.amount<=0){alert('Enter a payment amount greater than R0.');return}if(calc.amount>Number(calc.invoice.total||0)){alert('Payment cannot be greater than the invoice total.');return}let paymentNumber=existing?.payment_number;if(!paymentNumber)try{paymentNumber=await nextPaymentNumber(session)}catch(e){alert(e.message);return}const allRecorded=payments.filter(p=>p.invoice_id===calc.invoice.id),recordedTotal=allRecorded.reduce((s,p)=>s+Number(p.amount||0),0),recordedBefore=allRecorded.filter(p=>p.id!==existing?.id).reduce((s,p)=>s+Number(p.amount||0),0),openingPaid=Math.max(0,Number(calc.invoice.amount_paid||0)-recordedTotal),newPaid=Math.min(Number(calc.invoice.total||0),openingPaid+recordedBefore+calc.amount),newBalance=Math.max(0,Number(calc.invoice.total||0)-newPaid);let status=calc.invoice.status;if(newPaid>=Number(calc.invoice.total||0)&&Number(calc.invoice.total||0)>0)status='Paid';else if(newPaid>0)status='Partially Paid';else if(status==='Paid'||status==='Partially Paid')status='Draft';const payload={owner_id:session.user.id,payment_number:paymentNumber,invoice_id:calc.invoice.id,client_id:calc.invoice.client_id,client_code:calc.invoice.client_code,client_name:calc.invoice.client_name,invoice_number:calc.invoice.invoice_number,payment_date:v.payment_date||today(),amount:calc.amount,method:v.method||'EFT',reference:v.reference||null,notes:v.notes||null};const result=existing?await window.kasituSupabase.from('payments').update(payload).eq('id',existing.id):await window.kasituSupabase.from('payments').insert(payload);if(result.error){alert(result.error.message);return}const invoiceResult=await window.kasituSupabase.from('invoices').update({amount_paid:newPaid,balance_due:newBalance,status}).eq('id',calc.invoice.id);if(invoiceResult.error){alert(invoiceResult.error.message);return}await loadData();closeModal();renderPayments()}
function quotationOptions(selected=''){return '<option value="">Start without a quotation...</option>'+quotations.map(q=>`<option value="${esc(q.id)}" ${q.id===selected?'selected':''}>${esc(q.quote_number)} — ${esc(q.client_name)} — ${money(q.total)}</option>`).join('')}
function defaultInvoiceItems(i){return i?.items?.length?i.items:[{description:'',quantity:1,unit_price:0}]}
function invoiceForm(i={}){
 i=i||{};const valid=i.due_date||addDays(i.invoice_date||today(),7);
 return `<div class="form-grid"><div class="field"><label>Quotation</label><select name="quotation_id">${quotationOptions(i.quotation_id||'')}</select></div><div class="field"><label>Invoice number</label><input name="invoice_number" value="${esc(i.invoice_number||'')}" placeholder="Auto-generated on save" readonly></div><div class="field"><label>Invoice date *</label><input type="date" name="invoice_date" value="${esc(i.invoice_date||today())}" required></div><div class="field"><label>Due date</label><input type="date" name="due_date" value="${esc(valid)}"></div><div class="field"><label>Status</label><select name="status">${['Draft','Sent','Partially Paid','Paid','Overdue','Cancelled'].map(x=>`<option ${x===(i.status||'Draft')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Amount paid (R)</label><input name="amount_paid" type="number" min="0" step="0.01" value="${Number(i.amount_paid||0).toFixed(2)}"></div><div class="field"><label>Discount (R)</label><input name="discount" type="number" min="0" step="0.01" value="${Number(i.discount||0).toFixed(2)}"></div><div class="field"><label>VAT rate (%)</label><input name="vat_rate" type="number" min="0" max="100" step="0.01" value="${Number(i.vat_rate||0)}"></div></div><div style="margin-top:20px"><div class="panel-head"><h3>Line items</h3><button type="button" class="btn" id="addInvoiceLine">+ Add item</button></div><div class="line-items" id="invoiceLines">${itemRows(defaultInvoiceItems(i)).replaceAll('name="item_qty"','name="invoice_qty"').replaceAll('name="item_price"','name="invoice_price"').replaceAll('name="item_description"','name="invoice_description"').replaceAll('name="item_total"','name="invoice_total"')}</div></div><div class="quote-summary" id="invoiceSummary"></div><div class="field" style="margin-top:20px"><label>Notes</label><textarea name="notes" placeholder="Optional invoice notes">${esc(i.notes||'')}</textarea></div><div class="field" style="margin-top:14px"><label>Terms & conditions</label><textarea name="terms" placeholder="Payment terms, due date, bank/payment details, etc.">${esc(i.terms||'Payment is due by the due date shown above. Please retain the invoice number as your payment reference.')}</textarea></div><div class="form-actions"><button type="button" class="btn" id="cancelModal">Cancel</button><button class="btn primary">Save Invoice</button></div>`}
function collectInvoiceItems(){return [...form.querySelectorAll('[data-line-row]')].map(row=>({description:row.querySelector('[name="invoice_description"]').value.trim(),quantity:Number(row.querySelector('[name="invoice_qty"]').value||0),unit_price:Number(row.querySelector('[name="invoice_price"]').value||0)})).filter(i=>i.description||i.unit_price>0)}
function calculateInvoice(){const items=collectInvoiceItems(),subtotal=items.reduce((s,i)=>s+i.quantity*i.unit_price,0),discount=Math.max(0,Number(form.querySelector('[name="discount"]')?.value||0)),taxable=Math.max(0,subtotal-discount),vatRate=Math.max(0,Number(form.querySelector('[name="vat_rate"]')?.value||0)),vat=taxable*vatRate/100,total=taxable+vat,paid=Math.min(total,Math.max(0,Number(form.querySelector('[name="amount_paid"]')?.value||0))),balance=Math.max(0,total-paid);form.querySelector('#invoiceSummary').innerHTML=`<div class="quote-summary-row"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><div class="quote-summary-row"><span>Discount</span><strong>− ${money(discount)}</strong></div><div class="quote-summary-row"><span>VAT (${vatRate.toFixed(2)}%)</span><strong>${money(vat)}</strong></div><div class="quote-summary-row total"><span>Total</span><strong>${money(total)}</strong></div><div class="quote-summary-row"><span>Amount paid</span><strong>${money(paid)}</strong></div><div class="quote-summary-row"><span>Balance due</span><strong>${money(balance)}</strong></div>`;form.querySelectorAll('[data-line-row]').forEach(row=>{const qty=Number(row.querySelector('[name="invoice_qty"]').value||0),price=Number(row.querySelector('[name="invoice_price"]').value||0);row.querySelector('[name="invoice_total"]').value=money(qty*price)});return {items,subtotal,discount,vatRate,vat,total,paid,balance}}
async function nextInvoiceNumber(session){const {data,error}=await window.kasituSupabase.from('invoices').select('invoice_number').eq('owner_id',session.user.id);if(error)throw error;const nums=(data||[]).map(r=>Number(String(r.invoice_number||'').match(/^KAS-I-\d{4}-(\d+)$/)?.[1]||0)).filter(Number.isFinite);return `KAS-I-${new Date().getFullYear()}-${String(Math.max(0,...nums)+1).padStart(3,'0')}`}
const isUuid=v=>/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(v||''));
async function saveInvoice(existing){
 const session=await getSession();if(!session)return;
 const v=values(),calc=calculateInvoice();
 const quotationId=isUuid(v.quotation_id)?v.quotation_id:null;
 let quote=quotationId?quotations.find(q=>q.id===quotationId):null;
 const existingId=isUuid(existing?.id)?existing.id:null;
 let client=quote&&isUuid(quote.client_id)?clients.find(c=>c._id===quote.client_id):null;
 if(!client&&quote&&isUuid(quote.client_id)){
  const lookup=await window.kasituSupabase.from('clients').select('*').eq('id',quote.client_id).maybeSingle();
  if(lookup.error){alert('Could not load the quotation client: '+lookup.error.message);return}
  const c=lookup.data;
  if(c)client={id:c.client_code,business:c.business_name,contact:c.contact_name||'',email:c.email||'',phone:c.phone||'',service:c.service||'',status:c.status,notes:c.notes||'',_id:c.id};
 }
 if(!client&&existingId&&isUuid(existing.client_id))client=clients.find(c=>c._id===existing.client_id);
 if(!client){alert('Could not find a client record linked to this quotation. Please verify the client selection and try again.');return}
 if(!isUuid(client._id)){alert('The client record has an invalid UUID. Please edit/save the client first, then create the invoice again.');return}
 if(!calc.items.length){alert('Add at least one invoice item.');return}
 let invoiceNumber=existingId?existing.invoice_number:null;
 if(!invoiceNumber)try{invoiceNumber=await nextInvoiceNumber(session)}catch(e){alert(e.message);return}
 let status=v.status;
 if(calc.total>0&&calc.paid>=calc.total)status='Paid';
 else if(calc.paid>0)status='Partially Paid';
 else if(status==='Partially Paid'||status==='Paid')status='Draft';
 const payload={owner_id:session.user.id,invoice_number:invoiceNumber,quotation_id:quote?.id||null,client_id:client._id,client_code:client.id,client_name:client.business,client_contact:client.contact||null,client_email:client.email||null,client_phone:client.phone||null,invoice_date:v.invoice_date||today(),due_date:v.due_date||null,status,line_items:calc.items,subtotal:calc.subtotal,discount:calc.discount,vat_rate:calc.vatRate,vat_amount:calc.vat,total:calc.total,amount_paid:calc.paid,balance_due:calc.balance,notes:v.notes||null,terms:v.terms||null};
 const result=existingId?await window.kasituSupabase.from('invoices').update(payload).eq('id',existingId):await window.kasituSupabase.from('invoices').insert(payload);
 if(result.error){alert(result.error.message);return}
 await loadData();closeModal();renderInvoices()
}
function quoteStatus(s){return `<span class="quote-status ${String(s||'Draft').toLowerCase()}">${esc(s||'Draft')}</span>`}
function quoteMini(){if(!quotations.length)return '<div class="empty">No quotations yet.<br><br><button class="btn primary" data-add="quotation">Create first quotation</button></div>';return quotations.slice(0,5).map(q=>`<div class="quote-card"><div class="quote-card-head"><div><div class="quote-number">${esc(q.quote_number)}</div><strong>${esc(q.client_name)}</strong></div><div style="text-align:right"><div class="quote-total">${money(q.total)}</div>${quoteStatus(q.status)}</div></div></div>`).join('')}
function renderQuotations(filter=''){title.textContent='Quotations';const rows=quotations.filter(q=>`${q.quote_number} ${q.client_name} ${q.status}`.toLowerCase().includes(filter.toLowerCase()));content.innerHTML=`<div class="section-head"><div><h2>Quotations</h2><p>Create, track and edit professional quotations.</p></div><div class="quote-toolbar"><input id="quoteSearch" class="search" placeholder="Search quotations..." value="${esc(filter)}"><button class="btn primary" data-add="quotation">+ New Quotation</button></div></div><div class="panel">${quoteTable(rows)}</div>`;document.getElementById('quoteSearch').addEventListener('input',e=>renderQuotations(e.target.value))}
function quoteTable(rows){if(!rows.length)return '<div class="empty">No quotations found. Create your first quotation.</div>';return `<div class="table-wrap"><table class="table"><thead><tr><th>Quote</th><th>Client</th><th>Date</th><th>Valid until</th><th>Status</th><th>Total</th><th></th></tr></thead><tbody>${rows.map(q=>`<tr><td><strong>${esc(q.quote_number)}</strong></td><td>${esc(q.client_name)}</td><td>${esc(q.quote_date||'—')}</td><td>${esc(q.valid_until||'—')}</td><td>${quoteStatus(q.status)}</td><td><strong>${money(q.total)}</strong></td><td><button class="btn" data-edit-quote="${esc(q.id)}">Edit</button> <button class="btn" data-create-invoice="${esc(q.id)}">Invoice</button></td></tr>`).join('')}</tbody></table></div>`}
function clientOptions(selected=''){return '<option value="">Select a client...</option>'+clients.map(c=>`<option value="${esc(c._id)}" ${c._id===selected?'selected':''}>${esc(c.id)} — ${esc(c.business)}</option>`).join('')}
function defaultItems(q){return q?.items?.length?q.items:[{description:'Business Website',quantity:1,unit_price:4999}]}
function itemRows(items){return items.map(i=>`<div class="line-item" data-line-row><div class="field line-description"><label>Item / Service</label><input name="item_description" value="${esc(i.description||'')}"></div><div class="field"><label>Qty</label><input name="item_qty" type="number" min="1" step="1" value="${Number(i.quantity||1)}"></div><div class="field"><label>Unit price</label><input name="item_price" type="number" min="0" step="0.01" value="${Number(i.unit_price||0).toFixed(2)}"></div><div class="field"><label>Line total</label><input name="item_total" readonly value="${money(Number(i.quantity||1)*Number(i.unit_price||0))}"></div><button type="button" class="btn line-remove" data-remove-line aria-label="Remove item">×</button></div>`).join('')}
function quoteForm(q={}){
 q=q||{};const valid=q.valid_until||addDays(q.quote_date||today(),14);
 return `<div class="form-grid"><div class="field"><label>Client *</label><select name="client_id" required>${clientOptions(q.client_id||'')}</select></div><div class="field"><label>Quotation number</label><input name="quote_number" value="${esc(q.quote_number||'')}" placeholder="Auto-generated on save" readonly></div><div class="field"><label>Quotation date *</label><input type="date" name="quote_date" value="${esc(q.quote_date||today())}" required></div><div class="field"><label>Valid until</label><input type="date" name="valid_until" value="${esc(valid)}"></div><div class="field"><label>Status</label><select name="status">${['Draft','Sent','Approved','Rejected','Expired'].map(x=>`<option ${x===(q.status||'Draft')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Deposit %</label><input name="deposit_rate" type="number" min="0" max="100" step="0.01" value="${Number(q.deposit_rate??50)}"></div><div class="field"><label>Discount (R)</label><input name="discount" type="number" min="0" step="0.01" value="${Number(q.discount||0).toFixed(2)}"></div><div class="field"><label>VAT rate (%)</label><input name="vat_rate" type="number" min="0" max="100" step="0.01" value="${Number(q.vat_rate||0)}"></div></div><div style="margin-top:20px"><div class="panel-head"><h3>Line items</h3><button type="button" class="btn" id="addQuoteLine">+ Add item</button></div><div class="line-items" id="quoteLines">${itemRows(defaultItems(q))}</div></div><div class="quote-summary" id="quoteSummary"></div><div class="field" style="margin-top:20px"><label>Notes</label><textarea name="notes" placeholder="Optional notes for the client">${esc(q.notes||'')}</textarea></div><div class="field" style="margin-top:14px"><label>Terms & conditions</label><textarea name="terms" placeholder="Payment terms, delivery terms, validity, etc.">${esc(q.terms||'Payment is due according to the agreed deposit and balance schedule. Quotation is valid until the date shown above.')}</textarea></div><div class="form-actions"><button type="button" class="btn" id="cancelModal">Cancel</button><button class="btn primary">Save Quotation</button></div>`
}
function collectQuoteItems(){return [...form.querySelectorAll('[data-line-row]')].map(row=>({description:row.querySelector('[name="item_description"]').value.trim(),quantity:Number(row.querySelector('[name="item_qty"]').value||0),unit_price:Number(row.querySelector('[name="item_price"]').value||0)})).filter(i=>i.description||i.unit_price>0)}
function calculateQuote(){const items=collectQuoteItems(),subtotal=items.reduce((s,i)=>s+i.quantity*i.unit_price,0),discount=Math.max(0,Number(form.querySelector('[name="discount"]')?.value||0)),taxable=Math.max(0,subtotal-discount),vatRate=Math.max(0,Number(form.querySelector('[name="vat_rate"]')?.value||0)),vat=taxable*vatRate/100,total=taxable+vat,depositRate=Math.min(100,Math.max(0,Number(form.querySelector('[name="deposit_rate"]')?.value||0))),deposit=total*depositRate/100,balance=Math.max(0,total-deposit);form.querySelector('#quoteSummary').innerHTML=`<div class="quote-summary-row"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><div class="quote-summary-row"><span>Discount</span><strong>− ${money(discount)}</strong></div><div class="quote-summary-row"><span>VAT (${vatRate.toFixed(2)}%)</span><strong>${money(vat)}</strong></div><div class="quote-summary-row total"><span>Total</span><strong>${money(total)}</strong></div><div class="quote-summary-row"><span>Deposit (${depositRate.toFixed(2)}%)</span><strong>${money(deposit)}</strong></div><div class="quote-summary-row"><span>Balance due</span><strong>${money(balance)}</strong></div>`;form.querySelectorAll('[data-line-row]').forEach(row=>{const qty=Number(row.querySelector('[name="item_qty"]').value||0),price=Number(row.querySelector('[name="item_price"]').value||0);row.querySelector('[name="item_total"]').value=money(qty*price)});return {items,subtotal,discount,vatRate,vat,total,depositRate,deposit,balance}}

