 const active=maintenance.filter(m=>m.status==='Active').length,paused=maintenance.filter(m=>m.status==='Paused').length,due=maintenance.filter(m=>m.next_service_date&&m.next_service_date<=today()&&!['Completed','Cancelled'].includes(m.status)).length;
