async function nextMaintenanceNumber(session){
 const {data,error}=await window.kasituSupabase.from('maintenance').select('maintenance_number').eq('owner_id',session.user.id);
 if(error)throw error;
 const nums=(data||[]).map(r=>Number(String(r.maintenance_number||'').match(/^KAS-M-\d{4}-(\d+)$/)?.[1]||0)).filter(Number.isFinite);
 return 'KAS-M-'+new Date().getFullYear()+'-'+String(Math.max(0,...nums)+1).padStart(3,'0')
}
async function saveMaintenance(existing){
 if(!maintenanceReady){alert('Run maintenance-schema.sql in Supabase before saving maintenance plans.');return}
 const v=values(),session=await getSession();if(!session)return;
 const client=clients.find(c=>c._id===v.client_id);
 if(!client){alert('Please select a client for this maintenance plan.');return}
 let number=existing?.maintenance_number;
 if(!number)try{number=await nextMaintenanceNumber(session)}catch(e){alert(e.message);return}
 const payload={owner_id:session.user.id,maintenance_number:number,title:v.title.trim(),client_id:client._id,client_code:client.id,client_name:client.business,service_type:v.service_type||'Other',status:v.status||'Planned',priority:v.priority||'Normal',billing_frequency:v.billing_frequency||'Monthly',fee:Math.max(0,Number(v.fee||0)),start_date:v.start_date||null,next_service_date:v.next_service_date||null,last_service_date:v.last_service_date||null,description:v.description||null,notes:v.notes||null};
 const result=existing?await window.kasituSupabase.from('maintenance').update(payload).eq('id',existing.id):await window.kasituSupabase.from('maintenance').insert(payload);
 if(result.error){alert(result.error.message);return}
 await loadData();closeModal();renderMaintenance()
}


