 const total=expenses.reduce((s,x)=>s+Number(x.amount||0),0),monthly=expenses.filter(x=>(x.expense_date||'').slice(0,7)===month).reduce((s,x)=>s+Number(x.amount||0),0),top=Object.entries(expenses.reduce((a,x)=>{a[x.category||'Other']=(a[x.category||'Other']||0)+Number(x.amount||0);return a},{})).sort((a,b)=>b[1]-a[1])[0];
 content.innerHTML='<div class="stats expense-stats"><div class="stat"><div class="stat-label">All expenses</div><div class="stat-value">'+money(total)+'</div><div class="stat-note">Total recorded spending</div></div><div class="stat"><div class="stat-label">This month</div><div class="stat-value">'+money(monthly)+'</div><div class="stat-note">'+esc(new Date().toLocaleDateString('en-ZA',{month:'long',year:'numeric'}))+'</div></div><div class="stat"><div class="stat-label">Records</div><div class="stat-value">'+expenses.length+'</div><div class="stat-note">Expenses logged</div></div><div class="stat"><div class="stat-label">Top category</div><div class="stat-value expense-top-category">'+esc(top?.[0]||'—')+'</div><div class="stat-note">'+(top?money(top[1]):'No expenses yet')+'</div></div></div><div class="section-head"><div><h2>Expenses</h2><p>Track business purchases, bills, payment methods and receipt links.</p></div><button class="btn primary" data-add="expense">+ Add Expense</button></div><div class="expense-toolbar"><input id="expenseSearch" class="search" placeholder="Search expenses..." value="'+esc(filter)+'"><select id="expenseCategory" class="search">'+['All',...expenseCategories].map(c=>'<option value="'+esc(c)+'" '+(c===category?'selected':'')+'>'+esc(c==='All'?'All categories':c)+'</option>').join('')+'</select><select id="expensePeriod" class="search"><option value="all" '+(period==='all'?'selected':'')+'>All time</option><option value="month" '+(period==='month'?'selected':'')+'>This month</option><option value="last-month" '+(period==='last-month'?'selected':'')+'>Last month</option><option value="year" '+(period==='year'?'selected':'')+'>This year</option></select></div><div class="panel"><div class="expense-filter-total"><span>Filtered total</span><strong>'+money(rows.reduce((s,x)=>s+Number(x.amount||0),0))+'</strong><span>'+rows.length+' record(s)</span></div>'+expenseTable(rows)+'</div>';
