function expenseForm(x={}){x=x||{};return '<div class="form-grid"><div class="field"><label>Expense name *</label><input name="title" required maxlength="180" value="'+esc(x.title||'')+'" placeholder="e.g. Website hosting renewal"></div><div class="field"><label>Expense number</label><input name="expense_number" readonly value="'+esc(x.expense_number||'')+'" placeholder="Auto-generated on save"></div><div class="field"><label>Category *</label><select name="category" required>'+expenseCategories.map(c=>'<option '+(c===(x.category||'Hosting & Domains')?'selected':'')+'>'+esc(c)+'</option>').join('')+'</select></div><div class="field"><label>Amount (R) *</label><input name="amount" type="number" min="0.01" step="0.01" required value="'+(x.amount==null?'':Number(x.amount).toFixed(2))+'" placeholder="0.00"></div><div class="field"><label>Expense date *</label><input type="date" name="expense_date" required value="'+esc(x.expense_date||today())+'"></div><div class="field"><label>Payment method</label><select name="payment_method">'+expenseMethods.map(m=>'<option '+(m===(x.payment_method||'EFT')?'selected':'')+'>'+esc(m)+'</option>').join('')+'</select></div><div class="field"><label>Vendor / supplier</label><input name="vendor" maxlength="180" value="'+esc(x.vendor||'')+'" placeholder="e.g. Render, Canva, supplier"></div><div class="field"><label>Receipt link</label><input type="url" name="receipt_url" value="'+esc(x.receipt_url||'')+'" placeholder="https://..."></div><div class="field full"><label>Notes</label><textarea name="notes" placeholder="Purpose, purchase details or other notes">'+esc(x.notes||'')+'</textarea></div></div><div class="form-actions"><button type="button" class="btn" id="cancelModal">Cancel</button><button class="btn primary">Save Expense</button></div>'}
async function nextExpenseNumber(session){const {data,error}=await window.kasituSupabase.from('expenses').select('expense_number').eq('owner_id',session.user.id);if(error)throw error;const nums=(data||[]).map(r=>Number(String(r.expense_number||'').match(/^KAS-EX-\d{4}-(\d+)$/)?.[1]||0)).filter(Number.isFinite);return 'KAS-EX-'+new Date().getFullYear()+'-'+String(Math.max(0,...nums)+1).padStart(3,'0')}
async function saveExpense(existing){if(!expensesReady){alert('Run expenses-schema.sql in Supabase before saving expenses.');return}const v=values(),session=await getSession();if(!session)return;const amount=Number(v.amount||0);if(!v.title?.trim()){alert('Enter an expense name.');return}if(!Number.isFinite(amount)||amount<=0){alert('Enter an amount greater than R0.');return}const receipt=v.receipt_url?.trim()||'';if(receipt&&!safeReceiptUrl(receipt)){alert('Please enter a valid receipt link beginning with http:// or https://.');return}let number=existing?.expense_number;if(!number)try{number=await nextExpenseNumber(session)}catch(e){alert(e.message);return}const payload={owner_id:session.user.id,expense_number:number,title:v.title.trim(),category:v.category||'Other',amount,expense_date:v.expense_date||today(),payment_method:v.payment_method||'EFT',vendor:v.vendor?.trim()||null,receipt_url:receipt||null,notes:v.notes?.trim()||null};const result=existing?await window.kasituSupabase.from('expenses').update(payload).eq('id',existing.id):await window.kasituSupabase.from('expenses').insert(payload);if(result.error){alert(result.error.message);return}await loadData();closeModal();renderExpenses()}
async function deleteExpense(id){if(!expensesReady)return;const x=expenses.find(e=>e.id===id);if(!x)return;if(!confirm('Delete "'+x.title+'" ('+money(x.amount)+')? This cannot be undone.'))return;const {error}=await window.kasituSupabase.from('expenses').delete().eq('id',id);if(error){alert(error.message);return}await loadData();renderExpenses()}

const documentTypes=['Contract','Quotation','Invoice','Receipt','Project File','Client Brief','ID / Registration','Report','Other'];
const allowedDocumentTypes='.pdf,.doc,.docx,.xls,.xlsx,.csv,.txt,.png,.jpg,.jpeg,.webp';
function documentClientOptions(selected=''){return '<option value="">Not linked to a client</option>'+clients.map(c=>'<option value="'+esc(c._id)+'" '+(c._id===selected?'selected':'')+'>'+esc(c.business)+' ('+esc(c.id)+')</option>').join('')}
function renderDocuments(filter='',type='All'){
 title.textContent='Documents';if(!documentsReady){content.innerHTML='<div class="panel"><h2>Documents setup needed</h2><p>Run <strong>documents-schema.sql</strong> in Supabase SQL Editor, then refresh.</p></div>';return}
 const expiryLimit=addDays(today(),30),rows=documents.filter(d=>[d.document_number,d.title,d.document_type,d.client_name,d.file_name,d.notes].join(' ').toLowerCase().includes(filter.toLowerCase())&&(type==='All'||d.document_type===type));
 const attached=documents.filter(d=>d.client_id).length,expiring=documents.filter(d=>d.expiry_date&&d.expiry_date>=today()&&d.expiry_date<=expiryLimit).length;
 content.innerHTML='<div class="stats document-stats"><div class="stat"><div class="stat-label">Documents</div><div class="stat-value">'+documents.length+'</div><div class="stat-note">Files stored securely</div></div><div class="stat"><div class="stat-label">Client-linked</div><div class="stat-value">'+attached+'</div><div class="stat-note">Attached to client records</div></div><div class="stat"><div class="stat-label">Expiring soon</div><div class="stat-value">'+expiring+'</div><div class="stat-note">Due within 30 days</div></div><div class="stat"><div class="stat-label">Storage</div><div class="stat-value">Private</div><div class="stat-note">Access controlled</div></div></div><div class="section-head"><div><h2>Documents</h2><p>Keep client contracts, receipts, quotations and project files in one secure place.</p></div><button class="btn primary" data-add="document">+ Upload Document</button></div><div class="document-toolbar"><input id="documentSearch" class="search" placeholder="Search documents..." value="'+esc(filter)+'"><select id="documentType" class="search">'+['All',...documentTypes].map(t=>'<option value="'+esc(t)+'" '+(t===type?'selected':'')+'>'+esc(t==='All'?'All document types':t)+'</option>').join('')+'</select></div><div class="panel">'+documentTable(rows)+'</div>';
 document.getElementById('documentSearch').addEventListener('input',e=>renderDocuments(e.target.value,document.getElementById('documentType').value));
 document.getElementById('documentType').addEventListener('change',e=>renderDocuments(document.getElementById('documentSearch').value,e.target.value))
}
function documentTable(rows){if(!rows.length)return '<div class="empty">No documents found. Upload your first file.<br><br><button class="btn primary" data-add="document">+ Upload Document</button></div>';return '<div class="table-wrap"><table class="table document-table"><thead><tr><th>Document</th><th>Type</th><th>Client</th><th>Date</th><th>Expiry</th><th>File</th><th>Actions</th></tr></thead><tbody>'+rows.map(d=>'<tr><td><strong>'+esc(d.title)+'</strong><br><span class="project-number">'+esc(d.document_number)+'</span></td><td><span class="document-type-badge">'+esc(d.document_type)+'</span></td><td>'+esc(d.client_name||'—')+'</td><td>'+esc(d.document_date||'—')+'</td><td>'+esc(d.expiry_date||'—')+'</td><td><span class="document-file-name">'+esc(d.file_name||'No file')+'</span><br><small>'+formatFileSize(d.file_size)+'</small></td><td><div class="document-actions"><button class="btn" data-download-document="'+esc(d.id)+'">View / Download</button><button class="btn" data-edit-document="'+esc(d.id)+'">Edit</button><button class="btn danger-btn" data-delete-document="'+esc(d.id)+'">Delete</button></div></td></tr>').join('')+'</tbody></table></div>'}
function formatFileSize(size){const n=Number(size||0);if(!n)return '—';if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';return (n/1048576).toFixed(2)+' MB'}
function documentForm(d={}){d=d||{};return '<div class="form-grid"><div class="field"><label>Document title *</label><input name="title" required maxlength="180" value="'+esc(d.title||'')+'" placeholder="e.g. Website maintenance agreement"></div><div class="field"><label>Document number</label><input name="document_number" readonly value="'+esc(d.document_number||'')+'" placeholder="Auto-generated on save"></div><div class="field"><label>Document type *</label><select name="document_type" required>'+documentTypes.map(t=>'<option '+(t===(d.document_type||'Contract')?'selected':'')+'>'+esc(t)+'</option>').join('')+'</select></div><div class="field"><label>Link to client</label><select name="client_id">'+documentClientOptions(d.client_id||'')+'</select></div><div class="field"><label>Document date</label><input type="date" name="document_date" value="'+esc(d.document_date||today())+'"></div><div class="field"><label>Expiry / renewal date</label><input type="date" name="expiry_date" value="'+esc(d.expiry_date||'')+'"></div><div class="field full"><label>Upload file '+(d.file_path?'(optional — leave blank to keep current file)':'*')+'</label><input type="file" name="document_file" accept="'+allowedDocumentTypes+'" '+(!d.file_path?'required':'')+'><small class="document-hint">PDF, Word, Excel, CSV, text or image files. Maximum 15 MB.</small>'+(d.file_name?'<div class="current-document-file">Current file: <strong>'+esc(d.file_name)+'</strong></div>':'')+'</div><div class="field full"><label>Notes</label><textarea name="notes" maxlength="5000" placeholder="Description, renewal details or other notes">'+esc(d.notes||'')+'</textarea></div></div><div class="form-actions"><button type="button" class="btn" id="cancelModal">Cancel</button><button class="btn primary">Save Document</button></div>'}
async function nextDocumentNumber(session){const {data,error}=await window.kasituSupabase.from('documents').select('document_number').eq('owner_id',session.user.id);if(error)throw error;const nums=(data||[]).map(r=>Number(String(r.document_number||'').match(/^KAS-D-\d{4}-(\d+)$/)?.[1]||0)).filter(Number.isFinite);return 'KAS-D-'+new Date().getFullYear()+'-'+String(Math.max(0,...nums)+1).padStart(3,'0')}
async function saveDocument(existing){if(!documentsReady){alert('Run documents-schema.sql in Supabase first.');return}const v=values(),session=await getSession();if(!session)return;const file=form.querySelector('[name="document_file"]')?.files?.[0]||null;if(!v.title?.trim()){alert('Enter a document title.');return}if(!existing&&!file){alert('Choose a file to upload.');return}if(file&&file.size>15*1024*1024){alert('This file is larger than 15 MB. Please choose a smaller file.');return}const client=clients.find(c=>c._id===v.client_id);let number=existing?.document_number;if(!number)try{number=await nextDocumentNumber(session)}catch(e){alert(e.message);return}const docId=existing?.id||crypto.randomUUID();let filePath=existing?.file_path||null,fileName=existing?.file_name||null,mimeType=existing?.mime_type||null,fileSize=existing?.file_size||null;if(file){const cleanName=file.name.normalize('NFKD').replace(/[^a-zA-Z0-9._-]+/g,'_').replace(/^\\.+/,'').slice(-180)||'upload';filePath=session.user.id+'/'+docId+'/'+Date.now()+'_'+cleanName;const uploaded=await window.kasituSupabase.storage.from('business-documents').upload(filePath,file,{contentType:file.type||'application/octet-stream',upsert:false});if(uploaded.error){alert('File upload failed: '+uploaded.error.message);return}fileName=file.name;mimeType=file.type||null;fileSize=file.size}const payload={owner_id:session.user.id,document_number:number,title:v.title.trim(),document_type:v.document_type||'Other',client_id:client?client._id:null,client_name:client?client.business:null,document_date:v.document_date||null,expiry_date:v.expiry_date||null,file_name:fileName,file_path:filePath,mime_type:mimeType,file_size:fileSize,notes:v.notes?.trim()||null};const result=existing?await window.kasituSupabase.from('documents').update(payload).eq('id',existing.id):await window.kasituSupabase.from('documents').insert({...payload,id:docId});if(result.error){if(filePath&&file)await window.kasituSupabase.storage.from('business-documents').remove([filePath]);alert(result.error.message);return}if(file&&existing?.file_path&&existing.file_path!==filePath)await window.kasituSupabase.storage.from('business-documents').remove([existing.file_path]);await loadData();closeModal();renderDocuments()}
async function downloadDocument(id){const d=documents.find(x=>x.id===id);if(!d?.file_path){alert('No file is attached to this document.');return}const tab=window.open('about:blank','_blank');const {data,error}=await window.kasituSupabase.storage.from('business-documents').createSignedUrl(d.file_path,60);if(error){if(tab)tab.close();alert('Could not open the file: '+error.message);return}if(tab)tab.location.href=data.signedUrl;else window.location.href=data.signedUrl}
async function deleteDocument(id){const d=documents.find(x=>x.id===id);if(!d)return;if(!confirm('Delete "'+d.title+'" and its stored file? This cannot be undone.'))return;if(d.file_path){const removed=await window.kasituSupabase.storage.from('business-documents').remove([d.file_path]);if(removed.error){alert('Could not remove the stored file: '+removed.error.message);return}}const {error}=await window.kasituSupabase.from('documents').delete().eq('id',id);if(error){alert(error.message);return}await loadData();renderDocuments()}
function projectStatus(s){return '<span class="project-status '+String(s||'Planning').toLowerCase().replace(/\s+/g,'-')+'">'+esc(s||'Planning')+'</span>'}
function renderProjects(filter=''){
 title.textContent='Projects';if(!projectsReady){content.innerHTML='<div class="panel"><h2>Projects setup needed</h2><p>Run the SQL in <strong>projects-schema.sql</strong> in your Supabase SQL Editor, then refresh this page. Your other Business Manager sections will continue to work.</p></div>';return}
 const rows=projects.filter(p=>(p.project_number+' '+p.project_name+' '+p.client_name+' '+p.status+' '+p.priority).toLowerCase().includes(filter.toLowerCase()));
 const active=projects.filter(p=>p.status==='In Progress').length,completed=projects.filter(p=>p.status==='Completed').length,overdue=projects.filter(p=>p.due_date&&p.due_date<today()&&!['Completed','Cancelled'].includes(p.status)).length;
 content.innerHTML='<div class="stats"><div class="stat"><div class="stat-label">All projects</div><div class="stat-value">'+projects.length+'</div><div class="stat-note">Projects in your register</div></div><div class="stat"><div class="stat-label">In progress</div><div class="stat-value">'+active+'</div><div class="stat-note">Currently underway</div></div><div class="stat"><div class="stat-label">Completed</div><div class="stat-value">'+completed+'</div><div class="stat-note">Delivered projects</div></div><div class="stat"><div class="stat-label">Past due</div><div class="stat-value">'+overdue+'</div><div class="stat-note">Needs a deadline review</div></div></div><div class="section-head"><div><h2>Projects</h2><p>Manage client work, deadlines, budgets and progress.</p></div><div class="quote-toolbar"><input id="projectSearch" class="search" placeholder="Search projects..." value="'+esc(filter)+'"><button class="btn primary" data-add="project">+ New Project</button></div></div><div class="panel">'+projectTable(rows)+'</div>';
 document.getElementById('projectSearch').addEventListener('input',e=>renderProjects(e.target.value))
}
function projectTable(rows){
 if(!rows.length)return '<div class="empty">No projects found. Create a project to track its progress and deadline.<br><br><button class="btn primary" data-add="project">+ Create Project</button></div>';
 return '<div class="table-wrap"><table class="table"><thead><tr><th>Project</th><th>Client</th><th>Status</th><th>Progress</th><th>Deadline</th><th>Budget</th><th></th></tr></thead><tbody>'+rows.map(p=>'<tr><td><strong>'+esc(p.project_name)+'</strong><br><span class="project-number">'+esc(p.project_number)+'</span></td><td>'+esc(p.client_name)+'</td><td>'+projectStatus(p.status)+'</td><td><div class="progress-track"><span style="width:'+Math.min(100,Math.max(0,Number(p.progress)||0))+'%"></span></div><small>'+Math.min(100,Math.max(0,Number(p.progress)||0))+'%</small></td><td>'+esc(p.due_date||'—')+'</td><td><strong>'+money(p.budget)+'</strong></td><td><button class="btn" data-edit-project="'+esc(p.id)+'">Edit</button></td></tr>').join('')+'</tbody></table></div>'
}
function projectForm(p={}){
 p=p||{};
 return '<div class="form-grid"><div class="field"><label>Project name *</label><input name="project_name" required maxlength="180" value="'+esc(p.project_name||'')+'" placeholder="e.g. Mumsy Braids website"></div><div class="field"><label>Project number</label><input name="project_number" readonly value="'+esc(p.project_number||'')+'" placeholder="Auto-generated on save"></div><div class="field"><label>Client *</label><select name="client_id" required>'+clientOptions(p.client_id||'')+'</select></div><div class="field"><label>Status</label><select name="status">'+['Planning','In Progress','On Hold','Completed','Cancelled'].map(x=>'<option '+(x===(p.status||'Planning')?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="field"><label>Priority</label><select name="priority">'+['Low','Normal','High','Urgent'].map(x=>'<option '+(x===(p.priority||'Normal')?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="field"><label>Progress (%)</label><input name="progress" type="number" min="0" max="100" step="1" value="'+Number(p.progress||0)+'" required></div><div class="field"><label>Start date</label><input type="date" name="start_date" value="'+esc(p.start_date||today())+'"></div><div class="field"><label>Due date</label><input type="date" name="due_date" value="'+esc(p.due_date||'')+'"></div><div class="field"><label>Budget (R)</label><input type="number" name="budget" min="0" step="0.01" value="'+Number(p.budget||0).toFixed(2)+'"></div><div class="field full"><label>Description</label><textarea name="description" placeholder="What needs to be delivered?">'+esc(p.description||'')+'</textarea></div><div class="field full"><label>Internal notes</label><textarea name="notes" placeholder="Milestones, next steps or reminders">'+esc(p.notes||'')+'</textarea></div></div><div class="form-actions"><button type="button" class="btn" id="cancelModal">Cancel</button><button class="btn primary">Save Project</button></div>'
}
async function nextProjectNumber(session){
 const {data,error}=await window.kasituSupabase.from('projects').select('project_number').eq('owner_id',session.user.id);
 if(error)throw error;
 const nums=(data||[]).map(r=>Number(String(r.project_number||'').match(/^KAS-PR-\d{4}-(\d+)$/)?.[1]||0)).filter(Number.isFinite);
 return 'KAS-PR-'+new Date().getFullYear()+'-'+String(Math.max(0,...nums)+1).padStart(3,'0')
}
async function saveProject(existing){
 if(!projectsReady){alert('Run projects-schema.sql in Supabase before saving projects.');return}
 const v=values(),session=await getSession();if(!session)return;
 const client=clients.find(c=>c._id===v.client_id);
 if(!client){alert('Please select a client for this project.');return}
 const progress=Math.min(100,Math.max(0,Number(v.progress||0)));
 let projectNumber=existing?.project_number;
 if(!projectNumber)try{projectNumber=await nextProjectNumber(session)}catch(e){alert(e.message);return}
 const payload={owner_id:session.user.id,project_number:projectNumber,project_name:v.project_name.trim(),client_id:client._id,client_code:client.id,client_name:client.business,description:v.description||null,status:v.status||'Planning',priority:v.priority||'Normal',start_date:v.start_date||null,due_date:v.due_date||null,budget:Math.max(0,Number(v.budget||0)),progress,notes:v.notes||null};
 if(payload.status==='Completed')payload.progress=100;
 const result=existing?await window.kasituSupabase.from('projects').update(payload).eq('id',existing.id):await window.kasituSupabase.from('projects').insert(payload);
 if(result.error){alert(result.error.message);return}
 await loadData();closeModal();renderProjects()
}

function openModal(type,existing=null){
 modal.hidden=false;document.body.style.overflow='hidden';modalTitle.textContent=existing?`Edit ${type}`:`Add New ${type}`;form.innerHTML=type==='Client'?clientForm(existing):type==='Lead'?leadForm(existing):type==='Quotation'?quoteForm(existing):type==='Invoice'?invoiceForm(existing):type==='Project'?projectForm(existing):type==='Maintenance'?maintenanceForm(existing):type==='Expense'?expenseForm(existing):type==='Document'?documentForm(existing):paymentForm(existing);requestAnimationFrame(()=>form.querySelector('input,select')?.focus());form.onsubmit=e=>{e.preventDefault();type==='Client'?saveClient(existing):type==='Lead'?saveLead(existing):type==='Quotation'?saveQuotation(existing):type==='Invoice'?saveInvoice(existing):type==='Project'?saveProject(existing):type==='Maintenance'?saveMaintenance(existing):type==='Expense'?saveExpense(existing):type==='Document'?saveDocument(existing):type==='Payment'?savePayment(existing):saveInvoice(existing)};document.getElementById('cancelModal')?.addEventListener('click',closeModal,{once:true});
 if(type==='Quotation'){document.getElementById('addQuoteLine').addEventListener('click',()=>{document.getElementById('quoteLines').insertAdjacentHTML('beforeend',itemRows([{description:'',quantity:1,unit_price:0}]));calculateQuote()});calculateQuote();form.addEventListener('input',e=>{if(e.target.closest('#quoteLines')||['discount','vat_rate','deposit_rate'].includes(e.target.name))calculateQuote()});form.addEventListener('click',e=>{if(e.target.closest('[data-remove-line]')){e.target.closest('[data-line-row]').remove();if(!document.querySelector('[data-line-row]'))document.getElementById('quoteLines').insertAdjacentHTML('beforeend',itemRows([{description:'',quantity:1,unit_price:0}]));calculateQuote()}})}
 if(type==='Invoice'){document.getElementById('addInvoiceLine').addEventListener('click',()=>{document.getElementById('invoiceLines').insertAdjacentHTML('beforeend',itemRows([{description:'',quantity:1,unit_price:0}]).replaceAll('name="item_qty"','name="invoice_qty"').replaceAll('name="item_price"','name="invoice_price"').replaceAll('name="item_description"','name="invoice_description"').replaceAll('name="item_total"','name="invoice_total"'));calculateInvoice()});calculateInvoice();form.addEventListener('input',e=>{if(e.target.closest('#invoiceLines')||['discount','vat_rate','amount_paid'].includes(e.target.name))calculateInvoice()});form.addEventListener('click',e=>{if(e.target.closest('[data-remove-line]')){e.target.closest('[data-line-row]').remove();if(!document.querySelector('#invoiceLines [data-line-row]'))document.getElementById('invoiceLines').insertAdjacentHTML('beforeend',itemRows([{description:'',quantity:1,unit_price:0}]).replaceAll('name="item_qty"','name="invoice_qty"').replaceAll('name="item_price"','name="invoice_price"').replaceAll('name="item_description"','name="invoice_description"').replaceAll('name="item_total"','name="invoice_total"'));calculateInvoice()}})}
if(type==='Payment'){form.dataset.paymentId=existing?.id||'';calculatePayment();form.addEventListener('input',e=>{if(e.target.name==='amount')calculatePayment()});form.addEventListener('change',e=>{if(e.target.name==='invoice_id')calculatePayment()})}
}
function clientForm(c={}){c=c||{};return `<div class="form-grid"><div class="field"><label>Business / Client name *</label><input name="business" required value="${esc(c.business)}"></div><div class="field"><label>Contact person</label><input name="contact" value="${esc(c.contact)}"></div><div class="field"><label>Email</label><input type="email" name="email" value="${esc(c.email)}"></div><div class="field"><label>Phone / WhatsApp</label><input name="phone" value="${esc(c.phone)}"></div><div class="field"><label>Service</label><input name="service" value="${esc(c.service)}" placeholder="e.g. Business Website"></div><div class="field"><label>Status</label><select name="status">${['Active','Prospect','Inactive'].map(x=>`<option ${x===(c.status||'Active')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field" style="grid-column:1/-1"><label>Notes</label><textarea name="notes">${esc(c.notes)}</textarea></div></div><div class="form-actions"><button type="button" class="btn" id="cancelModal">Cancel</button><button class="btn primary">Save Client</button></div>`}
function leadForm(l={}){l=l||{};return `<div class="form-grid"><div class="field"><label>Business / Person *</label><input name="business" required value="${esc(l.business)}"></div><div class="field"><label>Contact person</label><input name="contact" value="${esc(l.contact)}"></div><div class="field"><label>Phone / WhatsApp</label><input name="phone" value="${esc(l.phone)}"></div><div class="field"><label>Email</label><input type="email" name="email" value="${esc(l.email)}"></div><div class="field"><label>Service requested</label><input name="service" value="${esc(l.service)}"></div><div class="field"><label>Status</label><select name="status">${['New','Contacted','Quoted','Won','Lost'].map(x=>`<option ${x===(l.status||'New')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Follow-up date</label><input type="date" name="followUp" value="${esc(l.followUp)}"></div><div class="field"><label>Source</label><input name="source" value="${esc(l.source)}" placeholder="WhatsApp, website, referral..."></div><div class="field" style="grid-column:1/-1"><label>Notes</label><textarea name="notes">${esc(l.notes)}</textarea></div></div><div class="form-actions"><button type="button" class="btn" id="cancelModal">Cancel</button><button class="btn primary">Save Lead</button></div>`}
function values(){return Object.fromEntries(new FormData(form).entries())}
async function saveClient(existing){const v=values(),session=await getSession();if(!session)return;const base={owner_id:session.user.id,business_name:v.business,contact_name:v.contact||null,email:v.email||null,phone:v.phone||null,service:v.service||null,status:v.status,notes:v.notes||null};let result;if(existing)result=await window.kasituSupabase.from('clients').update({...base,client_code:existing.id}).eq('id',existing._id);else{const latest=await window.kasituSupabase.from('clients').select('client_code').eq('owner_id',session.user.id);if(latest.error){alert(latest.error.message);return}const used=(latest.data||[]).map(r=>Number(String(r.client_code||'').match(/^KAS-\d{4}-(\d+)$/)?.[1]||0)).filter(Number.isFinite);let next=Math.max(0,...used)+1;for(let i=0;i<5;i++){const code=`KAS-${new Date().getFullYear()}-${String(next).padStart(3,'0')}`;result=await window.kasituSupabase.from('clients').insert({...base,client_code:code});if(!result.error)break;if(!String(result.error.message||'').toLowerCase().includes('duplicate key'))break;next++}}if(result.error){alert(result.error.message);return}await loadData();closeModal();renderClients()}
async function saveLead(existing){const v=values(),session=await getSession();if(!session)return;const payload={owner_id:session.user.id,business_name:v.business,contact_name:v.contact||null,phone:v.phone||null,email:v.email||null,service_requested:v.service||null,status:v.status,follow_up_date:v.followUp||null,source:v.source||null,notes:v.notes||null};const result=existing?await window.kasituSupabase.from('leads').update(payload).eq('id',existing.id):await window.kasituSupabase.from('leads').insert(payload);if(result.error){alert(result.error.message);return}await loadData();closeModal();renderLeads()}
async function nextQuoteNumber(session){const {data,error}=await window.kasituSupabase.from('quotations').select('quote_number').eq('owner_id',session.user.id);if(error)throw error;const nums=(data||[]).map(r=>Number(String(r.quote_number||'').match(/^KAS-Q-\d{4}-(\d+)$/)?.[1]||0)).filter(Number.isFinite);return `KAS-Q-${new Date().getFullYear()}-${String(Math.max(0,...nums)+1).padStart(3,'0')}`}
async function saveQuotation(existing){const session=await getSession();if(!session)return;const v=values(),calc=calculateQuote(),client=clients.find(c=>c._id===v.client_id);if(!client){alert('Please select a client.');return}if(!calc.items.length){alert('Add at least one quotation item.');return}let quoteNumber=existing?.quote_number;if(!quoteNumber)try{quoteNumber=await nextQuoteNumber(session)}catch(e){alert(e.message);return}const payload={owner_id:session.user.id,quote_number:quoteNumber,client_id:client._id,client_code:client.id,client_name:client.business,client_contact:client.contact||null,client_email:client.email||null,client_phone:client.phone||null,quote_date:v.quote_date||today(),valid_until:v.valid_until||null,status:v.status,line_items:calc.items,subtotal:calc.subtotal,discount:calc.discount,vat_rate:calc.vatRate,vat_amount:calc.vat,total:calc.total,deposit_rate:calc.depositRate,deposit_amount:calc.deposit,balance_amount:calc.balance,notes:v.notes||null,terms:v.terms||null};const result=existing?await window.kasituSupabase.from('quotations').update(payload).eq('id',existing.id):await window.kasituSupabase.from('quotations').insert(payload);if(result.error){alert(result.error.message);return}await loadData();closeModal();renderQuotations()}
function closeModal(){modal.hidden=true;document.body.style.overflow=''}
function bindNavigation(){document.querySelectorAll('.nav-item[data-view]').forEach(btn=>btn.addEventListener('click',()=>{sidebar.classList.remove('open');render(btn.dataset.view);document.querySelectorAll('.nav-item').forEach(x=>x.classList.remove('active'));btn.classList.add('active')}));document.getElementById('mobileMenu').addEventListener('click',()=>sidebar.classList.toggle('open'));document.getElementById('modalClose').addEventListener('click',closeModal);modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.getElementById('signOutButton').addEventListener('click',async()=>{await window.kasituSupabase.auth.signOut();window.location.replace('login.html')})}
function bindNavigationButtons(){document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>document.querySelector(`[data-view="${b.dataset.go}"]`)?.click()));document.querySelectorAll('[data-add="project"]').forEach(b=>b.addEventListener('click',()=>openModal('Project')));document.querySelectorAll('[data-add="client"]').forEach(b=>b.addEventListener('click',()=>openModal('Client')));document.querySelectorAll('[data-add="lead"]').forEach(b=>b.addEventListener('click',()=>openModal('Lead')));document.querySelectorAll('[data-add="quotation"]').forEach(b=>b.addEventListener('click',()=>openModal('Quotation')));document.querySelectorAll('[data-add="invoice"]').forEach(b=>b.addEventListener('click',()=>openModal('Invoice')));document.querySelectorAll('[data-add="payment"]').forEach(b=>b.addEventListener('click',()=>openModal('Payment')));document.querySelectorAll('[data-add="maintenance"]').forEach(b=>b.addEventListener('click',()=>openModal('Maintenance')));document.querySelectorAll('[data-add="expense"]').forEach(b=>b.addEventListener('click',()=>openModal('Expense')));document.querySelectorAll('[data-add="document"]').forEach(b=>b.addEventListener('click',()=>openModal('Document')))}
function render(view){if(view==='projects')renderProjects();else if(view==='maintenance')renderMaintenance();else if(view==='expenses')renderExpenses();else if(view==='documents')renderDocuments();else if(view==='clients')renderClients();else if(view==='leads')renderLeads();else if(view==='quotations')renderQuotations();else if(view==='invoices')renderInvoices();else if(view==='payments')renderPayments();else renderDashboard();bindNavigationButtons()}
document.addEventListener('click',e=>{const cid=e.target.closest('[data-edit-client]')?.dataset.editClient;if(cid){openModal('Client',clients.find(c=>c.id===cid));return}const lid=e.target.closest('[data-edit-lead]')?.dataset.editLead;if(lid){openModal('Lead',leads.find(l=>l.id===lid));return}const qid=e.target.closest('[data-edit-quote]')?.dataset.editQuote;if(qid){openModal('Quotation',quotations.find(q=>q.id===qid));return}const ciid=e.target.closest('[data-create-invoice]')?.dataset.createInvoice;if(ciid){const q=quotations.find(x=>x.id===ciid);const client=q?clients.find(c=>c._id===q.client_id):null;openModal('Invoice',{quotation_id:q?.id||'',client_id:client?._id||'',client_name:client?.business||q?.client_name||'',items:q?.items||[],subtotal:q?.subtotal||0,discount:q?.discount||0,vat_rate:q?.vat_rate||0,total:q?.total||0,amount_paid:0,balance_due:q?.total||0,status:'Draft',invoice_date:today(),due_date:addDays(today(),7),notes:'Invoice created from '+(q?.quote_number||'quotation')});return}const iid=e.target.closest('[data-edit-invoice]')?.dataset.editInvoice;if(iid){openModal('Invoice',invoices.find(i=>i.id===iid));return}const projid=e.target.closest('[data-edit-project]')?.dataset.editProject;if(projid){openModal('Project',projects.find(p=>p.id===projid));return}const maintid=e.target.closest('[data-edit-maintenance]')?.dataset.editMaintenance;if(maintid){openModal('Maintenance',maintenance.find(m=>m.id===maintid));return}const exid=e.target.closest('[data-edit-expense]')?.dataset.editExpense;if(exid){openModal('Expense',expenses.find(x=>x.id===exid));return}const delid=e.target.closest('[data-delete-expense]')?.dataset.deleteExpense;if(delid){deleteExpense(delid);return}const docid=e.target.closest('[data-edit-document]')?.dataset.editDocument;if(docid){openModal('Document',documents.find(d=>d.id===docid));return}const ddel=e.target.closest('[data-delete-document]')?.dataset.deleteDocument;if(ddel){deleteDocument(ddel);return}const dview=e.target.closest('[data-download-document]')?.dataset.downloadDocument;if(dview){downloadDocument(dview);return}const pid=e.target.closest('[data-edit-payment]')?.dataset.editPayment;if(pid){openModal('Payment',payments.find(p=>p.id===pid));return}if(e.target.id==='cancelModal')closeModal()});
(async()=>{if(!window.supabase||!window.KASITU_SUPABASE_URL||!window.KASITU_SUPABASE_PUBLISHABLE_KEY){content.innerHTML='<div class="panel"><h2>Configuration missing</h2><p>Supabase configuration is missing.</p></div>';return}window.kasituSupabase=window.supabase.createClient(window.KASITU_SUPABASE_URL,window.KASITU_SUPABASE_PUBLISHABLE_KEY);const ok=await loadData();if(!ok)return;bindNavigation();renderDashboard()})();